// Generate frontend/README.md (what npm shows for the `freebrowse` package) from
// the repository README, so the embedding docs have one source of truth. The
// output is gitignored and regenerated by `npm run build:package` / prepack.
import { readFileSync, writeFileSync } from "node:fs";

const root = readFileSync(new URL("../../README.md", import.meta.url), "utf8");
const section = (title) => {
  const start = root.indexOf(`## ${title}`);
  if (start < 0) throw new Error(`README section not found: ${title}`);
  const next = root.indexOf("\n## ", start + 1);
  return root.slice(start, next < 0 ? root.length : next).trimEnd();
};
const out = [
  "# freebrowse",
  "",
  "FreeBrowse is a browser-based neuroimaging viewer built on [NiiVue](https://github.com/niivue/mono).",
  "This package lets another web app mount the FreeBrowse UI around a NiiVue instance the host",
  "controls. Full project documentation: https://github.com/freesurfer/freebrowse",
  "",
  section("Embedding FreeBrowse in your own app (npm package)").replace(
    /\]\(frontend\/examples\/\)/g,
    "](https://github.com/freesurfer/freebrowse/tree/main/frontend/examples/)",
  ),
  "",
  section("Driving FreeBrowse from your own code"),
  "",
  section("NiiVue documents (`.nvd`)"),
  "",
].join("\n");
writeFileSync(new URL("../README.md", import.meta.url), out);
console.log("frontend/README.md generated from ../README.md");
